/* Real provider APIs through authenticated loopback service; no secret persistence. */
names.apis=['AI API 采样','AI API sampling'];
let apiProviders=[],apiMarket=new URLSearchParams(location.hash.split('?')[1]).get('api_market')==='US'?'US':'CN',apiRuns=[],apiActive=null,apiTimer=null,apiSelected=new Set(),apiDraft={CN:{},US:{}};
const apiQuestions={CN:'在中国购买保湿精华，干燥缺水肤质有哪些值得比较的具体产品？请最多列出五款，并在可用时提供官方产品来源。\n在中国购买抗老面霜，有哪些值得比较的具体产品？请说明选择依据和局限，并在可用时提供官方产品来源。',US:'Which facial serums are worth comparing for dry, dehydrated skin in the United States? Name up to five specific products and include official product sources when available.\nWhich anti-aging moisturizers are worth comparing in the United States? Name specific products, explain selection criteria and limitations, and include official sources when available.'};
function apiCapture(){for(const k of ['website','brand','skus','questions']){const e=$('#api-'+k);if(e)apiDraft[apiMarket][k]=e.value}}
function apiSetMarket(m){apiCapture();apiMarket=m;apiActive=null;apiSelected.clear();clearTimeout(apiTimer);const params=new URLSearchParams(location.hash.split('?')[1]);params.set('api_market',m);history.replaceState(null,'',location.hash.split('?')[0]+'?'+params.toString());render()}
function apiProviderName(id){return apiProviders.find(p=>p.id===id)?.name||id}
function apiPage(){const draft=apiDraft[apiMarket],ps=apiProviders.filter(p=>p.markets.includes(apiMarket));return `<div class="diag-hero"><div><div class="diag-eyebrow">LIVE API · ${apiMarket} · BRAND & SKU</div><h2>${t('让真实回答成为评分依据。','Measure real API answers.')}</h2><p>${t('同一市场、同一题集，分别比较各模型 API 的品牌和 SKU 提及率。','Compare brand and SKU mention rates across APIs using the same market and question set.')}</p></div><button onclick="connectToolRunner()">${runnerToken?t('执行器已连接','Runner connected'):t('连接本机执行器','Connect local runner')}</button></div><div class="actions api-tabs"><button class="${apiMarket==='CN'?'primary':''}" onclick="apiSetMarket('CN')">中国 · CN</button><button class="${apiMarket==='US'?'primary':''}" onclick="apiSetMarket('US')">美国 · US</button><button onclick="apiRefresh()">刷新连接与记录</button></div><p class="notice">API 结果独立于网页 / App 实测。${runnerToken?'密钥仅存于本机执行器内存，重启后需重新配置。':'线上展示接口配置入口；真实调用由本机执行器完成。打开本机工作台可自动连接。'} <a href="http://127.0.0.1:8770/#/w/demo/apis" target="_blank" rel="noopener">打开本机工作台 ↗</a></p><div class="tool-grid">${ps.map(p=>`<section class="card tool-card"><div class="card-head"><h2>${esc(p.name)}</h2><span class="tag ${p.configured?'badge':'warn'}">${p.configured?'已配置 · 待采样验证':'待配置密钥'}</span></div><p class="subtitle">${esc(p.boundary)}</p><p class="mono">${esc(p.configuration?.model||p.model_hint)}</p><div class="actions"><button onclick="apiConfigure('${p.id}')">${p.configured?'修改配置':'配置 API'}</button><label><input type="checkbox" ${p.configured?'':'disabled'} ${apiSelected.has(p.id)?'checked':''} onchange="this.checked?apiSelected.add('${p.id}'):apiSelected.delete('${p.id}')"> 加入本次采样</label>${p.docs?`<a href="${esc(p.docs)}" target="_blank" rel="noopener noreferrer">官方文档 ↗</a>`:''}</div></section>`).join('')||'<p>正在加载平台目录…</p>'}</div><section class="card api-plan"><div class="card-head"><h2>采样任务 · ${apiMarket==='CN'?'中国市场':'美国市场'}</h2><span class="tag">${apiMarket==='CN'?'中文题集':'English questions'}</span></div><div class="grid"><div>${input('品牌官网（记录测量对象，不会自动发送给模型）','api-website',draft.website||'')}${input('品牌名称 / 别名（用 | 分隔；用于本地匹配）','api-brand',draft.brand||'')}${area('SKU：每行“商品名称 | 精确别名 | 其他别名”；不填则只测品牌','api-skus',draft.skus||'')}</div><div>${area('测试问题：每行一个，最多 10 个；建议不提示目标品牌或 SKU','api-questions',draft.questions??apiQuestions[apiMarket])}<p class="subtitle">只向所选平台发送每条问题，不把官网、品牌清单或 SKU 清单加入提示。调用可能产生服务商费用；每批最多 64 次，无自动重试。联网开关仅表示请求，实际搜索使用以返回证据为准。</p></div></div><button class="primary" id="api-start" onclick="apiStart()">开始所选平台采样</button><p id="api-error" class="error" role="alert"></p></section><section class="card api-plan"><div class="card-head"><h2>运行与证据 · ${apiMarket}</h2><button onclick="apiRefresh()">刷新</button></div><div class="actions">${apiRuns.filter(r=>r.market===apiMarket).map(r=>`<button class="small" onclick="apiOpenRun('${r.id}')">${esc(r.created_at.slice(0,16))} · ${esc(r.status)} · ${r.samples.length}/${r.planned}</button>`).join('')||'<p class="muted">尚无该市场的 API 采样记录；网页试测不混入此处。</p>'}</div><div id="api-results">${apiResultHtml()}</div></section>`}
function apiResultHtml(){const r=apiActive;if(!r||r.market!==apiMarket)return '';return `<p class="mono">${esc(r.id)} · ${esc(r.status)} · ${r.samples.length}/${r.planned} calls</p><p class="notice">评分口径：100 × 完整、未提示目标的回答中精确别名命中数 ÷ 此类有效回答数。失败、截断不计为零；必须结合完成覆盖率。分数只描述本批 API 样本，不是市场整体曝光率，也不是推荐排名。</p>${table(['平台 API','完整 / 已尝试 / 计划','品牌提及分 / 100','SKU 提及分 / 100'],(r.summary||[]).map(s=>`<tr><td>${esc(apiProviderName(s.provider))}<div class="mono">${esc(r.configuration[s.provider].model)}</div></td><td>${s.complete} / ${s.attempted} / ${r.prompts.length}<div class="row-meta">品牌非提示有效回答 ${s.discovery_complete}</div></td><td>${s.brand_mention_score??'—'}</td><td>${s.skus.map(k=>`${esc(k.name)}：${k.score??'—'} <span class="muted">(${k.mentions}/${k.denominator})</span>`).join('<br>')||'未提供 SKU'}</td></tr>`).join(''))}<div class="actions" style="margin:16px 0"><button onclick="apiExport('${r.id}')">↓ 导出证据包（含原始 API 响应与 hash）</button></div>${r.samples.map((s,i)=>`<details class="api-answer"><summary>${esc(apiProviderName(s.provider))} · 问题 ${s.question_index+1} · ${esc(s.status)}${s.brand_prompted?' · 品牌提示题（排除发现分）':''}</summary><p>${esc(s.prompt)}</p>${s.error?`<p class="error">${esc(s.error)}</p>`:`<p class="mono">返回模型：${esc(s.model_returned||'未返回')} · ${s.latency_ms} ms · 搜索请求 ${s.search_requested?'开':'关'} / 搜索执行证据 ${s.search_observed?'有':'未确认'}</p><pre class="evidence">${esc(s.answer)}</pre><p>品牌命中：${esc(s.brand_match||'未命中')} · 引用元数据 ${s.citations.length} 条 · 检索来源 ${s.retrieved_sources.length} 条（两者分别记录）</p><pre class="evidence">${esc(JSON.stringify({citations:s.citations,retrieved_sources:s.retrieved_sources,usage:s.usage},null,2))}</pre><p class="mono">sha256:${esc(s.raw_sha256)}</p>`}</details>`).join('')}`}
function apiConfigure(id){apiCapture();const p=apiProviders.find(x=>x.id===id),c=p.configuration||{};if(!runnerToken)return connectToolRunner();modal(head(esc(p.name))+`<p>${esc(p.boundary)}</p><p class="notice">密钥仅保存在本机执行器内存，不写入网页存储或公开站点。配置成功不代表已通过真实请求验证。</p>${input('API Key / APIPassword','api-key','','password')}${input('精确模型 ID（Perplexity 填 preset）','api-model',c.model||'')}${input('API base URL','api-base',c.base_url||p.base_url)}<p class="subtitle">${esc(p.model_hint)}</p>${p.search?`<label><input type="checkbox" id="api-search" ${c.search?'checked':''}> 请求原生联网搜索（受模型权限支持）</label>`:''}<div class="actions" style="margin-top:20px"><button class="primary" id="api-save" onclick="apiSave('${id}')">保存到本机会话</button>${p.configured?`<button onclick="apiClear('${id}')">清除会话密钥</button>`:''}</div><p class="error" id="api-config-error" role="alert"></p>`);$('#api-key').autocomplete='off'}
async function apiSave(id){try{const payload={provider:id,key:$('#api-key').value,model:$('#api-model').value,base_url:$('#api-base').value,search:!!$('#api-search')?.checked};$('#api-save').disabled=true;await toolFetch('ai/configure',{method:'POST',body:JSON.stringify(payload)});$('#api-key').value='';closeOverlay();await apiRefresh();toast('配置已存入本机会话；现在可以选择平台采样')}catch(e){$('#api-config-error').textContent=e.message;if($('#api-save'))$('#api-save').disabled=false}}
async function apiClear(id){await toolFetch('ai/configure',{method:'POST',body:JSON.stringify({provider:id,clear:true})});apiSelected.delete(id);closeOverlay();await apiRefresh()}
async function apiRefresh(){try{apiCapture();if(runnerToken){const [p,r]=await Promise.all([toolFetch('ai/providers'),toolFetch('ai/runs')]);apiProviders=p.providers;apiRuns=r.runs;if(apiActive)apiActive=apiRuns.find(r=>r.id===apiActive.id)||apiActive}if(page==='apis')render()}catch(e){toast(e.message)}}
async function apiStart(){apiCapture();try{const d=apiDraft[apiMarket];const skus=(d.skus||'').split('\n').filter(x=>x.trim()).map(line=>{const a=line.split('|').map(x=>x.trim()).filter(Boolean);return {name:a[0],aliases:a}});const payload={market:apiMarket,providers:[...apiSelected],website:d.website||'',brand_aliases:(d.brand||'').split('|').map(x=>x.trim()).filter(Boolean),skus,prompts:(d.questions||'').split('\n').map(x=>x.trim()).filter(Boolean)};if(!payload.providers.length)throw Error('请先配置并勾选至少一个平台');if(!payload.brand_aliases.length)throw Error('请填写用于匹配的品牌名称');$('#api-start').disabled=true;const r=await toolFetch('ai/run',{method:'POST',body:JSON.stringify(payload)});await apiOpenRun(r.id);toast('已提交 '+r.planned+' 次 API 调用')}catch(e){if($('#api-error'))$('#api-error').textContent=e.message;if($('#api-start'))$('#api-start').disabled=false}}
async function apiOpenRun(id){try{apiCapture();clearTimeout(apiTimer);apiActive=await toolFetch('ai/run?id='+encodeURIComponent(id));await apiRefresh();if(['queued','running'].includes(apiActive.status))apiTimer=setTimeout(()=>{if(page==='apis')apiOpenRun(id)},4000)}catch(e){toast(e.message)}}
async function apiExport(id){try{downloadJSON(await toolFetch('ai/export?id='+encodeURIComponent(id)),'signal-api-evidence-'+id+'.json')}catch(e){toast(e.message)}}
const beforeApiRender=render;
render=function(){beforeApiRender();if(page==='apis'){document.querySelector('#view').innerHTML=apiPage();document.querySelector('.page-head .actions').innerHTML='';document.querySelector('main > .notice').innerHTML='<span>真实 API 采样 · 与虚构演示数据隔离。市场指问题语境，不表示采样节点位于当地。</span>';const note=document.querySelector('.page-head .subtitle');if(note)note.textContent='配置接口 → 运行题集 → 品牌 / SKU 表现 → 原始证据'}};
async function loadApiProviders(){try{const r=await fetch('ai-providers.json');if(!r.ok)throw Error('平台目录加载失败');apiProviders=await r.json();if(page==='apis')render();if(['127.0.0.1','localhost'].includes(location.hostname)){const s=await fetch('/api/tools/session');if(s.ok){runnerToken=(await s.json()).token;runnerBase='';await apiRefresh()}}}catch(e){toast(e.message)}}
